$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.IO.Compression
$out=Join-Path $PSScriptRoot 'repository_verified'
New-Item -ItemType Directory -Force -Path $out | Out-Null
$source='C:/Users/Lorie/Downloads/Contents - Copy.docx'
$stream=[IO.File]::Open($source,'Open','Read','ReadWrite')
$zip=[IO.Compression.ZipArchive]::new($stream,'Read')
$reader=[IO.StreamReader]::new($zip.GetEntry('word/document.xml').Open())
[xml]$xml=$reader.ReadToEnd();$reader.Dispose()
$ns=[Xml.XmlNamespaceManager]::new($xml.NameTable)
$ns.AddNamespace('w','http://schemas.openxmlformats.org/wordprocessingml/2006/main')
$ns.AddNamespace('a','http://schemas.openxmlformats.org/drawingml/2006/main')
$lines=[Collections.Generic.List[string]]::new()
foreach($node in $xml.SelectSingleNode('//w:body',$ns).ChildNodes){
 if($node.LocalName -eq 'tbl'){
  $all=($node.SelectNodes('.//w:t',$ns)|ForEach-Object {$_.InnerText}) -join ''
  if($all -match 'Figure 4\.1'){$lines.Add('@PAIR entry');continue}
  if($all -match 'Figure 4\.3'){$lines.Add('===PAGE===');$lines.Add('## 4.3 Wireframes continued');$lines.Add('@PAIR work');continue}
  if($all -match 'Figure 4\.5'){$lines.Add('===PAGE===');$lines.Add('## 4.3 Wireframes continued');$lines.Add('@PAIR review');continue}
  $rowIndex=0
  foreach($row in $node.SelectNodes('w:tr',$ns)){
   $values=@();foreach($cell in $row.SelectNodes('w:tc',$ns)){$values+=(($cell.SelectNodes('.//w:t',$ns)|ForEach-Object {$_.InnerText}) -join '')}
   $lines.Add('| '+($values -join ' | ')+' |')
   if($rowIndex -eq 0){$lines.Add('|'+((@('---')*$values.Count) -join '|')+'|')};$rowIndex++
  }
 }elseif($node.LocalName -eq 'p'){
  $text=($node.SelectNodes('.//w:t',$ns)|ForEach-Object {$_.InnerText}) -join ''
  $image=$node.SelectNodes('.//a:blip',$ns).Count -gt 0
  if(!$text -and !$image){continue}
  if($image -and $text -match 'Figure 5\.1'){$lines.Add('@IMAGE architecture');$lines.Add('@CAPTION Figure 5.1 System architecture');continue}
  if($text -match '^(3 Requirements|4 UI Design|5 System Architecture|6 Database Schema|6\.2 Cloud|7 Firebase|8 Local Database|9 Setup|10 Limitations)'){$lines.Add('===PAGE===')}
  if($text -match '^\d+\.\d+ '){$lines.Add('## '+$text)}elseif($text -match '^\d+ '){$lines.Add('# '+$text)}elseif($text -match '^Figure '){$lines.Add('@CAPTION '+$text)}else{
   if($node.SelectSingleNode('w:pPr/w:numPr',$ns)){$lines.Add('- '+$text)}else{$lines.Add($text)}
  }
  if($image -and $text -match '^6\.1'){$lines.Add('@IMAGE erd')}
 }
}
$zip.Dispose();$stream.Dispose()
$md=$lines -join "`n"
[IO.File]::WriteAllText((Join-Path $out 'attached_source.md'),$md,[Text.UTF8Encoding]::new($false))
function Change([string]$old,[string]$new){if(!$script:md.Contains($old)){throw "Missing source text: $old"};$script:md=$script:md.Replace($old,$new)}
